import React from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';
import { LocationMarkerFilledIcon } from '@dynatrace/strato-icons';

import { TooltipText } from '../../section-components/atoms/TooltipText.js';
import { TooltipInfoContent } from '../../section-components/TooltipInfoContent.js';
import { TooltipItem } from '../../section-components/TooltipItem.js';
import { TooltipSymbolContent } from '../../section-components/TooltipSymbolContent.js';

export interface GeoItemProps {
  latitude: string | number;
  longitude: string | number;
  actions?: () => React.ReactElement;
}

export const GeoItem = ({ latitude, longitude, actions }: GeoItemProps) => {
  return (
    <TooltipItem actions={actions}>
      <TooltipSymbolContent>
        <LocationMarkerFilledIcon
          style={{ fill: Colors.Text.Neutral.Default }}
        />
      </TooltipSymbolContent>
      <TooltipInfoContent>
        <TooltipText>{`${latitude}, ${longitude}`}</TooltipText>
      </TooltipInfoContent>
    </TooltipItem>
  );
};
